<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick,computed} from 'vue'
import type {ExperimentTracker} from './experimentTracker'
import {experimentTime,normalizedSelection,cropPixels,experimentPageLabel} from './experimentRuntime'
import {captureScreen} from './screenCapture'
import {capturePage} from './pageCapture'
import {localExperiment} from './experimentLocal'
import {useDialogAccess} from './dialogAccess'
import {useOverlayHost} from './overlayHost'
const props=defineProps<{tracker:ExperimentTracker;projectId?:string;page:string}>(),host=useOverlayHost()
const editor=ref(false),capturing=ref(false),selecting=ref(false),sending=ref(false),image=ref(''),text=ref(''),category=ref('think_aloud'),error=ref(''),notice=ref(''),selection=ref<any>(null),picture=ref<HTMLImageElement>(),file=ref<HTMLInputElement>(),meta=ref<any>(null),pending=ref<any>(null),draft=ref(false),parentRegion=ref<any>(null)
const frame=ref(''),framePicture=ref<HTMLImageElement>(),frameSelection=ref<any>(null),regionDialog=ref<HTMLElement>(),notes=ref<HTMLTextAreaElement>(),dialog=ref<HTMLElement>(),activeDialog=computed(()=>selecting.value?regionDialog.value:dialog.value),keyboardTrap=useDialogAccess(()=>editor.value||selecting.value,activeDialog)
let captureToken=0,returnToEditor=false,frameScope:any=null,frameParent:any=null
let start:{x:number,y:number}|null=null,dragging=false,noticeTimer:ReturnType<typeof setTimeout>
watch([editor,selecting,capturing],()=>props.tracker.state.overlayPage=editor.value||selecting.value||capturing.value?'feedback':'')
function context(){return {projectId:props.projectId||null,page:props.page,runId:props.tracker.recording()?props.tracker.state.run.id:null,elapsedMs:props.tracker.recording()?Math.round(props.tracker.elapsed()):null}}
function focusNotes(){void nextTick(()=>notes.value?.focus())}
function cancelCapture(){captureToken++;capturing.value=false;selecting.value=false;frame.value='';frameSelection.value=null;dragging=false;start=null;editor.value=returnToEditor}
async function take(mode:'page'|'screen'='page'){
 if(capturing.value||sending.value)return
 returnToEditor=editor.value;error.value='';const scope=context(),token=++captureToken;editor.value=false;selecting.value=false;capturing.value=true;props.tracker.record('screenshot_open',{mode})
 try{
  let result:string
  if(mode==='screen')result=await captureScreen()
  else{await nextTick();result=await capturePage()}
  if(token!==captureToken)return
  frame.value=result;frameSelection.value=null;frameParent=null;frameScope=scope;selecting.value=true
  void nextTick(()=>regionDialog.value?.focus())
 }catch(e:any){if(token!==captureToken)return;meta.value||=scope;error.value=mode==='page'?'网页截图暂未成功，可重试，或在「其他截图方式」中粘贴／选择图片。':e.name==='NotAllowedError'?'已取消屏幕共享。可使用网页框选或粘贴截图。':e.message;editor.value=true}
 finally{if(token===captureToken)capturing.value=false}
}
function closeEditor(){captureToken++;editor.value=false}
function writeNote(){captureToken++;capturing.value=false;selecting.value=false;frame.value='';meta.value||=context();editor.value=true;focusNotes()}
function open(){if(draft.value){editor.value=true;focusNotes();return}void take()}
function point(e:PointerEvent){const r=framePicture.value!.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function down(e:PointerEvent){if(!framePicture.value?.naturalWidth||e.button!==0)return;e.preventDefault();start=point(e);dragging=true;frameSelection.value=normalizedSelection(start,start);(e.currentTarget as Element).setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(dragging&&start)frameSelection.value=normalizedSelection(start,point(e))}
function up(){if(!dragging)return;dragging=false;start=null;const r=framePicture.value?.getBoundingClientRect(),box=frameSelection.value;if(!r||!box||box.w*r.width<8||box.h*r.height<8){frameSelection.value=null;return}acceptRegion()}
function acceptRegion(whole=false){
 const im=framePicture.value,region=whole?{x:0,y:0,w:1,h:1}:frameSelection.value;if(!im?.naturalWidth||!region)return
 const box=cropPixels(region,im.naturalWidth,im.naturalHeight),canvas=document.createElement('canvas');canvas.width=box.w;canvas.height=box.h;canvas.getContext('2d')!.drawImage(im,box.x,box.y,box.w,box.h,0,0,box.w,box.h)
 image.value=canvas.toDataURL('image/png');selection.value={x:0,y:0,w:1,h:1};parentRegion.value=frameParent?{x:frameParent.x+region.x*frameParent.w,y:frameParent.y+region.y*frameParent.h,w:region.w*frameParent.w,h:region.h*frameParent.h}:region;meta.value=frameScope;pending.value=null;frame.value='';selecting.value=false;editor.value=true;focusNotes()
}
function adjustRegion(){if(!image.value)return;returnToEditor=true;frame.value=image.value;frameParent=parentRegion.value;frameScope=meta.value;frameSelection.value=null;editor.value=false;selecting.value=true;void nextTick(()=>regionDialog.value?.focus())}
async function loadFile(blob:Blob){captureToken++;capturing.value=false;selecting.value=false;if(!blob.type.startsWith('image/')){error.value='请选择图片文件';return}if(blob.size>8*1024*1024){error.value='图片超过8MB，请先缩小截图范围';return}image.value=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(blob)});selection.value={x:0,y:0,w:1,h:1};parentRegion.value=null;meta.value=context();pending.value=null;error.value='';editor.value=true;focusNotes()}
function paste(e:ClipboardEvent){if(!editor.value)return;const blob=Array.from(e.clipboardData?.items||[]).find(item=>item.type.startsWith('image/'))?.getAsFile();if(blob){e.preventDefault();void loadFile(blob)}}
function crop(){if(!image.value)return '';if(!selection.value||!picture.value)throw Error('截图尚未载入，请稍候');const im=picture.value,box=cropPixels(selection.value,im.naturalWidth,im.naturalHeight);const canvas=document.createElement('canvas');canvas.width=box.w;canvas.height=box.h;canvas.getContext('2d')!.drawImage(im,box.x,box.y,box.w,box.h,0,0,box.w,box.h);return canvas.toDataURL('image/png')}
async function save(){
 sending.value=true;error.value='';let persisted=false
 try{
  const whole=selection.value&&selection.value.x===0&&selection.value.y===0&&selection.value.w===1&&selection.value.h===1;const cropped=parentRegion.value&&whole?image.value:crop();if(!cropped&&!text.value.trim())throw Error('请填写便笺或附上截图')
  const content={...meta.value,text:text.value,category:category.value,image:cropped,region:parentRegion.value&&selection.value?{x:parentRegion.value.x+selection.value.x*parentRegion.value.w,y:parentRegion.value.y+selection.value.y*parentRegion.value.h,w:selection.value.w*parentRegion.value.w,h:selection.value.h*parentRegion.value.h}:selection.value||{}}
  const signature=JSON.stringify(content)
  if(pending.value?.signature!==signature)pending.value={signature,body:{id:crypto.randomUUID(),...content}}
  await localExperiment('drafts','put',{...content,pending:pending.value},'screenshot');draft.value=true;persisted=true
  await props.tracker.request('/experiment-notes','POST',pending.value.body)
  await localExperiment('drafts','delete',undefined,'screenshot');draft.value=false;pending.value=null;image.value='';text.value='';selection.value=null;meta.value=null;closeEditor();notice.value='截图便笺已保存';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',3500)
 }catch(e:any){error.value=e.message+(persisted?'；选区和便笺已保存在本机，可重试发送':'；尚未写入本机，内容仍在当前窗口，请勿关闭')}finally{sending.value=false}
}
function keyboard(e:KeyboardEvent){if(e.key==='Escape'&&(editor.value||selecting.value||capturing.value)){e.preventDefault();e.stopImmediatePropagation();if(selecting.value||capturing.value)cancelCapture();else closeEditor()}}
function resized(){if(selecting.value||capturing.value)cancelCapture()}
onMounted(async()=>{document.addEventListener('paste',paste);document.addEventListener('keydown',keyboard,true);window.addEventListener('resize',resized);try{const saved=await localExperiment('drafts','get',undefined,'screenshot');if(saved){image.value=saved.image;text.value=saved.text;category.value=saved.category;meta.value={projectId:saved.projectId,page:saved.page,runId:saved.runId,elapsedMs:saved.elapsedMs};pending.value=saved.pending;parentRegion.value=saved.region;selection.value=saved.image?{x:0,y:0,w:1,h:1}:null;draft.value=true}}catch{}})
onUnmounted(()=>{captureToken++;document.removeEventListener('paste',paste);document.removeEventListener('keydown',keyboard,true);window.removeEventListener('resize',resized);props.tracker.state.overlayPage='';clearTimeout(noticeTimer)})
</script>
<template><Teleport :to="host"><aside v-show="!capturing&&!editor&&!selecting" class="feedback-float" data-experiment-ignore data-screenshot-ignore aria-label="截图与实验工具"><button class="capture-button" :title="draft?'继续未发送的截图便笺':'直接框选当前网页，无需共享屏幕'" @click="open"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/></svg>{{draft?'继续便笺':'截图便笺'}}</button><button class="text-note-button" aria-label="仅写文字便笺" @click="writeNote">文字便笺 ✎</button><button v-if="tracker.recording()||tracker.state.stopping" class="recording-pill" @click="tracker.state.panel=true"><i/>{{tracker.state.stopping?'待同步':experimentTime(tracker.state.elapsedMs)}}<small>{{tracker.state.pending?' · '+tracker.state.pending+' 待同步':''}}</small></button></aside>
 <aside v-if="capturing" class="feedback-float" data-experiment-ignore data-screenshot-ignore><span class="capture-waiting" role="status">正在准备截图…</span><button class="capture-button" @click="cancelCapture">取消截图</button></aside><div v-if="notice" class="capture-notice" role="status" data-experiment-ignore data-screenshot-ignore>{{notice}}</div>
 <section v-if="selecting" ref="regionDialog" class="page-region-picker" role="dialog" aria-modal="true" aria-label="拖动框选网页区域" tabindex="-1" data-experiment-ignore data-screenshot-ignore @keydown="keyboardTrap" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="dragging=false;frameSelection=null"><img ref="framePicture" :src="frame" alt="当前可见页面，拖动框选后直接写便笺" draggable="false"><div v-if="frameSelection" class="capture-selection page-region-selection" :style="{left:frameSelection.x*100+'%',top:frameSelection.y*100+'%',width:frameSelection.w*100+'%',height:frameSelection.h*100+'%'}"/><div class="page-region-toolbar" @pointerdown.stop @pointerup.stop><span>拖动框选 · 松开写便笺</span><button @click="acceptRegion(true)">截取整个可见页面</button><button @click="cancelCapture">取消 <kbd>Esc</kbd></button></div></section>
 <div v-if="editor" class="capture-backdrop" data-experiment-ignore data-screenshot-ignore><section ref="dialog" class="capture-editor" @keydown="keyboardTrap" role="dialog" aria-modal="true" aria-labelledby="capture-title"><header><div><small>SCREENSHOT NOTE</small><h2 id="capture-title">截图便笺</h2><p>{{image?'已截取选区，直接填写便笺即可。':'可直接写文字，也可框选当前网页或粘贴系统截图。'}}</p></div><button type="button" class="icon-button" aria-label="关闭截图便笺" :disabled="sending" @click="closeEditor">×</button></header><div class="capture-body"><div class="capture-left"><div class="capture-image-tools"><button type="button" :disabled="sending" @click="take()">{{image?'重新框选网页':'框选当前网页'}}</button><button type="button" v-if="image" :disabled="sending" @click="adjustRegion">裁切图片</button><details class="capture-alternatives"><summary>其他截图方式</summary><div><button type="button" :disabled="sending" @click="file?.click()">选择图片</button><button type="button" :disabled="sending" @click="take('screen')">截取其他窗口（需授权）</button><small>也可直接粘贴系统截图。</small></div></details><input ref="file" type="file" accept="image/*" hidden @change="($event.target as HTMLInputElement).files?.[0]&&loadFile(($event.target as HTMLInputElement).files![0]!)"></div><div class="capture-preview"><div v-if="image" class="capture-image-area"><img ref="picture" :src="image" alt="已选取的截图区域" draggable="false"></div><p v-else>尚未添加截图。可以直接填写文字便笺。</p></div></div><form class="capture-note" @submit.prevent="save"><small>所在模块：{{experimentPageLabel(meta?.page||page)}}{{meta?.runId?' · 已关联当前实验':' · 独立便笺'}}</small><label>反馈类型<select v-model="category"><option value="think_aloud">思考／文字反馈</option><option value="bug">问题或 Bug</option><option value="discomfort">不舒服／困惑的地方</option><option value="idea">改进想法</option></select></label><label>便笺 notes<textarea ref="notes" v-model="text" rows="12" maxlength="12000" placeholder="刚才在想什么？哪里卡住、不符合预期，或让你感到不舒服？"/></label><p v-if="error" class="capture-error" role="alert">{{error}}</p><button type="submit" class="primary" :disabled="sending||(!text.trim()&&!image)">{{sending?'保存中…':'保存截图便笺'}}</button><small>只在当前网页本地生成截图，无需屏幕共享。点击保存才上传选区和文字。</small></form></div></section></div></Teleport></template>
<style scoped>.feedback-float{position:fixed;z-index:170;right:18px;top:45%;display:flex;flex-direction:column;gap:7px;align-items:end}.capture-waiting{font-size:11px;padding:10px;border-radius:12px;background:#fffef5ed;color:#899a77}.capture-button{display:flex;align-items:center;gap:8px;border:1px solid #b7c7b1;background:#fffff8ee;box-shadow:0 5px 24px #243d2320;border-radius:24px;color:#56714d;padding:11px 15px;font-size:12px;backdrop-filter:blur(12px)}.text-note-button{font-size:10px;color:#89967d;border:1px solid #d5decc;border-radius:14px;background:#fbfdf3e8;padding:5px 10px}.recording-pill{border:1px solid #d5ddcd;border-radius:16px;background:#fafcf5e8;padding:5px 9px;font-size:10px;color:#8a927d}.recording-pill i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#b06b5f;margin-right:6px}.recording-pill small{font-size:9px}.capture-notice{position:fixed;right:24px;bottom:28px;z-index:180;background:#edf5e9;color:#526e48;border:1px solid #b8cbae;padding:14px 20px;border-radius:12px;font-size:12px}.capture-backdrop{position:fixed;inset:0;z-index:190;background:#182821b8;backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:34px}.capture-editor{width:min(1540px,94vw);max-height:94dvh;overflow:auto;background:#fbfcf6;border:1px solid #d8e3cf;border-radius:18px;box-shadow:0 30px 100px #061b2c55;color:#506849}.capture-editor header{display:flex;justify-content:space-between;padding:22px 28px;border-bottom:1px solid #e2e8db;align-items:start}.capture-editor header small{font-size:9px;color:#a0ab93;letter-spacing:.15em}.capture-editor h2{font-size:20px;margin:6px 0}.capture-editor header p{font-size:11px;color:#8c9a80;margin:6px 0}.capture-body{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px;padding:22px 28px}.capture-left{min-width:0}.capture-image-tools{display:flex;gap:8px;margin-bottom:14px}.capture-image-tools button{font-size:11px}.capture-preview{min-height:360px;height:65dvh;display:flex;align-items:center;justify-content:center;background:#e8ede2;border:1px solid #d8e0cd;border-radius:10px;overflow:hidden}.capture-preview>p{font-size:12px;color:#9aab88;max-width:280px;line-height:1.8}.capture-image-area{position:relative;display:inline-block;touch-action:none;line-height:0;max-width:100%;max-height:100%}.capture-image-area img{display:block;max-width:100%;max-height:65dvh;object-fit:contain;user-select:none}.capture-selection{position:absolute;border:2px solid #4f8c6b;background:#c5efcb1a;box-shadow:0 0 0 200vw #172a1955;pointer-events:none;box-sizing:border-box}.capture-note{display:flex;flex-direction:column;gap:16px;min-width:0}.capture-note label{font-size:12px;margin:0}.capture-note label textarea,.capture-note label select{margin-top:8px}.capture-note small{font-size:10px;color:#95a486;line-height:1.8}.capture-note textarea{resize:vertical}.capture-error{font-size:11px;line-height:1.8;color:#ac7862;margin:0}.page-region-picker{position:fixed;inset:0;z-index:200;background:#f5f7f2;cursor:crosshair;touch-action:none;overflow:hidden;outline:none}.page-region-picker>img{display:block;width:100%;height:100%;user-select:none}.page-region-picker:before{content:"";position:absolute;inset:0;background:#142a2224;pointer-events:none}.page-region-selection{z-index:1;background:transparent;border-color:#ecf8dc}.page-region-toolbar{position:absolute;z-index:2;top:20px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:18px;background:#fbfff7f5;border:1px solid #b6c9ad;box-shadow:0 8px 30px #1d332a40;padding:11px 16px;border-radius:12px;cursor:default;white-space:nowrap;color:#506b47;font-size:12px}.page-region-toolbar button{font-size:11px}.page-region-toolbar kbd{margin-left:5px;font-size:10px;color:#8c9c80}.capture-alternatives{position:relative;font-size:11px;color:#849576}.capture-alternatives>summary{cursor:pointer;padding:9px}.capture-alternatives>div{position:absolute;z-index:2;top:35px;left:0;display:flex;flex-direction:column;gap:10px;min-width:220px;padding:14px;background:#fbfcf6;border:1px solid #d1ddc9;border-radius:10px;box-shadow:0 8px 30px #1e352a26}.capture-alternatives small{font-size:10px;color:#8e9d80}</style>
